insert into public.daily_questions (id, prompt, category, status, room) values ('7448acc9-20f0-4ea8-85eb-f218cff4423c', 'You can bring ONE fictional villain to Thanksgiving dinner. Who''s getting a plate?', 'Unsorted', 'Approved', 'public');
